#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 48
#define MAXT 64

typedef float v8 __attribute__((vector_size(32)));

static inline v8 ld(const float *p) { v8 v; memcpy(&v, p, 32); return v; }
static inline void st(float *p, v8 v) { memcpy(p, &v, 32); }

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int mr, int nr, int acc)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};
    for (int k = 0; k < kc; k++) {
        v8 b0 = ld(b), b1 = ld(b + 8);
        float a0 = a[0], a1 = a[1], a2 = a[2], a3 = a[3], a4 = a[4], a5 = a[5];
        c00 += a0 * b0; c01 += a0 * b1;
        c10 += a1 * b0; c11 += a1 * b1;
        c20 += a2 * b0; c21 += a2 * b1;
        c30 += a3 * b0; c31 += a3 * b1;
        c40 += a4 * b0; c41 += a4 * b1;
        c50 += a5 * b0; c51 += a5 * b1;
        a += MR;
        b += NR;
    }
    if (mr == MR && nr == NR) {
#define STR(r, x0, x1) do { float *p = c + (r) * ldc; \
        if (acc) { x0 += ld(p); x1 += ld(p + 8); } \
        st(p, x0); st(p + 8, x1); } while (0)
        STR(0, c00, c01); STR(1, c10, c11); STR(2, c20, c21);
        STR(3, c30, c31); STR(4, c40, c41); STR(5, c50, c51);
#undef STR
    } else {
        float t[MR][NR];
        st(t[0], c00); st(t[0] + 8, c01);
        st(t[1], c10); st(t[1] + 8, c11);
        st(t[2], c20); st(t[2] + 8, c21);
        st(t[3], c30); st(t[3] + 8, c31);
        st(t[4], c40); st(t[4] + 8, c41);
        st(t[5], c50); st(t[5] + 8, c51);
        for (int i = 0; i < mr; i++)
            for (int j = 0; j < nr; j++) {
                if (acc) c[i * ldc + j] += t[i][j];
                else c[i * ldc + j] = t[i][j];
            }
    }
}

typedef struct {
    const float *A, *B;
    float *C, *Bp;
    int n, np;
    int counter;
} ctx_t;

static void pack_b_panel(ctx_t *x, int jp)
{
    int n = x->n, np = x->np;
    for (int k0 = 0; k0 < n; k0 += KC) {
        int kc = n - k0 < KC ? n - k0 : KC;
        float *dst = x->Bp + (size_t)k0 * np * NR + (size_t)jp * kc * NR;
        int j0 = jp * NR;
        int nr = n - j0 < NR ? n - j0 : NR;
        for (int k = 0; k < kc; k++) {
            const float *src = x->B + (size_t)(k0 + k) * n + j0;
            float *d = dst + k * NR;
            if (nr == NR) {
                memcpy(d, src, NR * sizeof(float));
            } else {
                int j = 0;
                for (; j < nr; j++) d[j] = src[j];
                for (; j < NR; j++) d[j] = 0.0f;
            }
        }
    }
}

static void *pack_worker(void *arg)
{
    ctx_t *x = (ctx_t *)arg;
    for (;;) {
        int jp = __atomic_fetch_add(&x->counter, 1, __ATOMIC_RELAXED);
        if (jp >= x->np) break;
        pack_b_panel(x, jp);
    }
    return NULL;
}

static void compute_chunk(ctx_t *x, int i0, float *Ap)
{
    int n = x->n, np = x->np;
    int mc = n - i0 < MC ? n - i0 : MC;
    int nmp = (mc + MR - 1) / MR;
    for (int k0 = 0; k0 < n; k0 += KC) {
        int kc = n - k0 < KC ? n - k0 : KC;
        for (int p = 0; p < nmp; p++) {
            float *d = Ap + (size_t)p * kc * MR;
            for (int r = 0; r < MR; r++) {
                int i = i0 + p * MR + r;
                if (i < i0 + mc) {
                    const float *src = x->A + (size_t)i * n + k0;
                    for (int k = 0; k < kc; k++) d[k * MR + r] = src[k];
                } else {
                    for (int k = 0; k < kc; k++) d[k * MR + r] = 0.0f;
                }
            }
        }
        const float *Bk = x->Bp + (size_t)k0 * np * NR;
        for (int jp = 0; jp < np; jp++) {
            int j0 = jp * NR;
            int nr = n - j0 < NR ? n - j0 : NR;
            const float *bp = Bk + (size_t)jp * kc * NR;
            for (int p = 0; p < nmp; p++) {
                int ib = i0 + p * MR;
                int mr = i0 + mc - ib < MR ? i0 + mc - ib : MR;
                kernel(kc, Ap + (size_t)p * kc * MR, bp,
                       x->C + (size_t)ib * n + j0, n, mr, nr, k0 > 0);
            }
        }
    }
}

static void *compute_worker(void *arg)
{
    ctx_t *x = (ctx_t *)arg;
    int nchunks = (x->n + MC - 1) / MC;
    float *Ap = NULL;
    if (posix_memalign((void **)&Ap, 64, (size_t)MC * KC * sizeof(float)) != 0)
        return NULL;
    for (;;) {
        int c = __atomic_fetch_add(&x->counter, 1, __ATOMIC_RELAXED);
        if (c >= nchunks) break;
        compute_chunk(x, c * MC, Ap);
    }
    free(Ap);
    return NULL;
}

static void run_parallel(void *(*fn)(void *), ctx_t *x, int nt)
{
    pthread_t th[MAXT];
    int created = 0;
    x->counter = 0;
    for (int t = 1; t < nt; t++) {
        if (pthread_create(&th[created], NULL, fn, x) == 0) created++;
    }
    fn(x);
    for (int t = 0; t < created; t++) pthread_join(th[t], NULL);
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    ctx_t x;
    x.A = A; x.B = B; x.C = C; x.n = n;
    x.np = (n + NR - 1) / NR;
    size_t bsz = (size_t)n * x.np * NR;
    if (posix_memalign((void **)&x.Bp, 64, bsz * sizeof(float)) != 0) {
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                float s = 0.0f;
                for (int k = 0; k < n; k++) s += A[(size_t)i * n + k] * B[(size_t)k * n + j];
                C[(size_t)i * n + j] = s;
            }
        return;
    }

    long ncpu = sysconf(_SC_NPROCESSORS_ONLN);
    if (ncpu < 1) ncpu = 1;
    if (ncpu > MAXT) ncpu = MAXT;
    int nchunks = (n + MC - 1) / MC;
    int nt = (int)ncpu;
    if ((double)n * n * n < 2e6) nt = 1;

    int ntp = nt < x.np ? nt : x.np;
    run_parallel(pack_worker, &x, ntp);

    int ntc = nt < nchunks ? nt : nchunks;
    run_parallel(compute_worker, &x, ntc);

    free(x.Bp);
}
